import{_ as t,o,c as a,a2 as d}from"./chunks/framework.Boholvbs.js";const m=JSON.parse(`{"title":"The Terminal UI","description":"Prompting, @-mentions, attachments, shell mode, queuing, interrupting, and the command palette inside prioricode's TUI.","frontmatter":{"title":"The Terminal UI","description":"Prompting, @-mentions, attachments, shell mode, queuing, interrupting, and the command palette inside prioricode's TUI."},"headers":[],"relativePath":"using/tui.md","filePath":"using/tui.md"}`),s={name:"using/tui.md"};function i(r,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<p>Run <code>prioricode</code> in a project and you get one screen: your prompt at the bottom, the conversation above, a sidebar to the side. Everything else is a keystroke away.</p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><p>A session starts the moment you submit your first prompt — there&#39;s no ceremony. Sessions are stored in the local database with a generated title (say <code>/rename</code> if you disagree with the one it picked). See <a href="./sessions.html">sessions</a> for resuming, forking, undo, and the storage story.</p><ul><li><code>/new</code> (or <code>&lt;leader&gt;n</code>) starts a fresh session; <code>/sessions</code> (<code>&lt;leader&gt;l</code>) lists and resumes old ones.</li><li><code>&lt;leader&gt;1</code>…<code>&lt;leader&gt;9</code> are quick slots — pin a session in the list with <code>ctrl+f</code> and jump back with one chord.</li><li>In <code>--auto</code>-free workflows, the agent stops and asks; see <a href="./permissions.html">permissions</a>.</li></ul><h2 id="writing-prompts" tabindex="-1">Writing prompts <a class="header-anchor" href="#writing-prompts" aria-label="Permalink to &quot;Writing prompts&quot;">​</a></h2><p>The input is a text editor in disguise. Standard bindings (<code>ctrl+a</code>/<code>ctrl+e</code>, word-wise <code>alt+f</code>/<code>alt+b</code>, <code>ctrl+w</code>, kill lines with <code>ctrl+u</code>/<code>ctrl+k</code>), multi-line with <code>shift+return</code> (or <code>ctrl+return</code>, <code>alt+return</code>, <code>ctrl+j</code>), and <code>up</code>/<code>down</code> walks your prompt history.</p><h3 id="mentions" tabindex="-1"><code>@</code> mentions <a class="header-anchor" href="#mentions" aria-label="Permalink to &quot;`@` mentions&quot;">​</a></h3><p>Type <code>@</code> to attach context, fuzzy-searched and ranked by how often you touch the files:</p><table tabindex="0"><thead><tr><th>Syntax</th><th>Attaches</th></tr></thead><tbody><tr><td><code>@src/api.ts</code></td><td>a file (or <code>@src/routes/</code> a directory)</td></tr><tr><td><code>@src/api.ts#10-20</code></td><td>just lines 10–20</td></tr><tr><td><code>@general</code></td><td>a subagent — routes the message through it</td></tr><tr><td><code>@&lt;name&gt;</code></td><td>a project reference (configured <code>references</code>)</td></tr><tr><td>MCP resources</td><td>when a connected server exposes them</td></tr></tbody></table><p>Slash commands complete from <code>/</code> at the start of a line — the full list is on the <a href="./../reference/slash-commands.html">slash-commands reference</a>.</p><h3 id="shell-mode" tabindex="-1">Shell mode <a class="header-anchor" href="#shell-mode" aria-label="Permalink to &quot;Shell mode&quot;">​</a></h3><p>Start an empty prompt with <code>!</code> and the next line runs in your shell, no model involved. Output stays in the transcript. <code>escape</code> (or backspace at the start) drops back to normal.</p><h2 id="getting-things-in" tabindex="-1">Getting things in <a class="header-anchor" href="#getting-things-in" aria-label="Permalink to &quot;Getting things in&quot;">​</a></h2><ul><li><strong>Paste an image or PDF</strong> with <code>ctrl+v</code> — it becomes an <code>[Image 1]</code> / <code>[PDF 1]</code> chip in your message and a real attachment on send.</li><li><strong>Paste long text</strong> (3+ lines or &gt;150 chars) and it collapses to a <code>[Pasted ~N lines]</code> chip that expands when you submit, keeping the transcript readable.</li><li><strong>Paste a file path or URL</strong> and it attaches itself — text inlined, binaries as attachments.</li><li><strong>Pipe into the prompt:</strong> <code>cat error.log | prioricode --prompt &quot;why did this fail&quot;</code> — piped stdin is prepended to the prompt.</li><li><strong>From your editor:</strong> the TUI picks up Zed&#39;s current selection as context, and <code>$EDITOR</code> integration works via <code>/editor</code> (see below).</li></ul><h2 id="while-the-agent-is-working" tabindex="-1">While the agent is working <a class="header-anchor" href="#while-the-agent-is-working" aria-label="Permalink to &quot;While the agent is working&quot;">​</a></h2><p>Keep typing — the input never blocks. New messages queue (you&#39;ll see a <strong>QUEUED</strong> badge) and are picked up as soon as the loop can take them. Manage the queue with <code>&lt;leader&gt;q</code>.</p><p><strong>To stop it:</strong> press <code>escape</code> — the footer says &quot;again to interrupt&quot;. Press <code>escape</code> a second time within five seconds and the session is aborted mid-step.</p><h2 id="your-other-keys" tabindex="-1">Your other keys <a class="header-anchor" href="#your-other-keys" aria-label="Permalink to &quot;Your other keys&quot;">​</a></h2><p><code>ctrl+p</code> opens the command palette: every command, searchable, no memorization required. The big-ticket defaults:</p><table tabindex="0"><thead><tr><th>Keys</th><th>Command</th></tr></thead><tbody><tr><td><code>ctrl+x</code></td><td>the leader key — prefix for most chords below (2 s window)</td></tr><tr><td><code>tab</code> / <code>shift+tab</code></td><td>next / previous agent</td></tr><tr><td><code>&lt;leader&gt;m</code>, <code>f2</code></td><td>model list / cycle recent models</td></tr><tr><td><code>&lt;leader&gt;c</code></td><td>compact the session</td></tr><tr><td><code>&lt;leader&gt;u</code> / <code>&lt;leader&gt;r</code></td><td>undo / redo the last message</td></tr><tr><td><code>&lt;leader&gt;b</code></td><td>hide the sidebar when you want the conversation full-bleed</td></tr><tr><td><code>&lt;leader&gt;e</code></td><td>compose in <code>$EDITOR</code></td></tr><tr><td><code>/help</code></td><td>keybinding cheatsheet in-app</td></tr></tbody></table><p>The complete table lives in the <a href="./../reference/keybinds.html">keybinds reference</a>, and all of it is rebindable in <code>tui.json</code> — see <a href="./../configure/tui.html">themes &amp; keybindings</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Forgot a chord? <code>ctrl+alt+k</code> toggles the which-key panel: a live overlay of what you can press next.</p></div><h2 id="sidebar-reading-the-screen" tabindex="-1">Sidebar &amp; reading the screen <a class="header-anchor" href="#sidebar-reading-the-screen" aria-label="Permalink to &quot;Sidebar &amp; reading the screen&quot;">​</a></h2><p>The sidebar carries the todo list (when the agent is planning multi-step work), context usage (tokens used vs the model&#39;s window), and your spend for the session. Press <code>&lt;leader&gt;h</code> to hide/show tool code, toggle timestamps with <code>/timestamps</code>, and cycle how much &quot;thinking&quot; is displayed with <code>/thinking</code>. The permission panel renders diffs — <code>ctrl+f</code> blows it up to fullscreen when the diff deserves it.</p><h2 id="exporting-the-conversation" tabindex="-1">Exporting the conversation <a class="header-anchor" href="#exporting-the-conversation" aria-label="Permalink to &quot;Exporting the conversation&quot;">​</a></h2><ul><li><code>/copy</code> puts a formatted transcript on your clipboard.</li><li><code>/export</code> opens a dialog (include thinking? tool details? metadata?) and hands you a markdown file — in <code>$EDITOR</code> if you have one set.</li></ul><h2 id="mini-mode" tabindex="-1">Mini mode <a class="header-anchor" href="#mini-mode" aria-label="Permalink to &quot;Mini mode&quot;">​</a></h2><p><code>prioricode --mini</code> is the same sessions, the same server, a much smaller footprint — a split-footer interface for tmux panes and SSH sessions over flaky connections. It speaks <code>/editor</code>, <code>/new</code>, <code>/exit</code>, and pipes cleanly; see <a href="./headless.html">headless &amp; scripting</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./sessions.html">Sessions</a> — Resume, fork, undo, compact, and the storage layout. <ul><li><a href="./agents.html">Agents &amp; modes</a> — What <code>tab</code> is actually cycling through.</li><li><a href="./../reference/slash-commands.html">Slash commands</a> — Every <code>/command</code>, with aliases.</li><li><a href="./../configure/tui.html">Themes &amp; keybinds</a> — Make it yours: 30+ themes, every binding overridable.</li></ul></li></ul>',30)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
